KINDS = ("btn", "tmp")

def decode(text):
    parts = text.split(":")
    if len(parts) != 3 or parts[0] not in KINDS:
        return None
    try:
        seq = int(parts[1])
    except ValueError:
        return None
    return parts[0], seq, parts[2]

print(decode("tmp:4:21"), decode("btn:x:A"), decode("tmp:5:2:1"))

