LABELS = ("temp", "light")

def to_csv(t_ms, row):
    return ",".join([str(t_ms)] + [str(row[k]) for k in LABELS])

print(to_csv(1500, {"light": 110, "temp": 22}))

def parse(line):
    t, temp, light = line.split(",")
    return int(t), int(temp), int(light)

rows = []
for line in ["time_ms,temp,light", "1000,21,90", "1.00,22,110", "2000,22,95"]:
    try:
        rows.append(parse(line))
    except ValueError:
        pass
print(len(rows), rows[-1])

